106	
107	    private final OwnerAuditLogger ownerAuditLogger;
108	
109	    public OwnerRestControllerV1(ClinicService clinicService,
110	                                 OwnerMapper ownerMapper,
111	                                 PetMapper petMapper,
112	                                 VisitMapper visitMapper,
113	                                 OwnerFieldsValidator ownerFieldsValidator,
114	                                 PostcodeValidator postcodeValidator,
115	                                 DisposableEmailDomainValidator disposableEmailDomainValidator,
116	                                 TelephoneNormalizer telephoneNormalizer,
117	                                 EmailNormalizer emailNormalizer,
118	                                 AddressResolver addressResolver,
119	                                 Households households,
120	                                 HouseholdDuplicateValidator householdDuplicateValidator,
121	                                 PossibleDuplicateDetector possibleDuplicateDetector,
122	                                 CityCapacityValidator cityCapacityValidator,
123	                                 DailyRegistrationLimitValidator dailyRegistrationLimitValidator,
124	                                 BusinessDayAdjuster businessDayAdjuster,
125	                                 RegistrationDateValidator registrationDateValidator,
126	                                 OwnerAuditLogger ownerAuditLogger) {
127	        this.clinicService = clinicService;
128	        this.ownerMapper = ownerMapper;
129	        this.petMapper = petMapper;
130	        this.visitMapper = visitMapper;
131	        this.ownerFieldsValidator = ownerFieldsValidator;
132	        this.postcodeValidator = postcodeValidator;
133	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
134	        this.telephoneNormalizer = telephoneNormalizer;
135	        this.emailNormalizer = emailNormalizer;
136	        this.addressResolver = addressResolver;
137	        this.households = households;
138	        this.householdDuplicateValidator = householdDuplicateValidator;
139	        this.possibleDuplicateDetector = possibleDuplicateDetector;
140	        this.cityCapacityValidator = cityCapacityValidator;
141	        this.dailyRegistrationLimitValidator = dailyRegistrationLimitValidator;
142	        this.businessDayAdjuster = businessDayAdjuster;
143	        this.registrationDateValidator = registrationDateValidator;
144	        this.ownerAuditLogger = ownerAuditLogger;
145	    }
146	
147	    /**
148	     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
149	     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
150	     */
151	    @InitBinder("ownerFieldsDto")
152	    void initOwnerFieldsBinder(WebDataBinder binder) {
153	        binder.addValidators(ownerFieldsValidator, postcodeValidator, disposableEmailDomainValidator);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
159	        Collection<Owner> owners;
160	        if (lastName != null) {
161	            owners = this.clinicService.findOwnerByLastName(lastName);
162	        } else {
163	            owners = this.clinicService.findAllOwners();
164	        }
165	        if (owners.isEmpty()) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
174	        Owner owner = this.clinicService.findOwnerById(ownerId);
175	        if (owner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
